def pre(samples):
    return all(0 <= x <= 1 for x in samples) and len(samples) <= 8

def post(samples, result):
    presses = 0
    run = 0
    armed = True
    for x in samples:
        if x == 1:
            run += 1
            if run == 3:
                presses += 1
                armed = False
        else:
            run = 0
            armed = True
    return result == presses

def is_pressed(x):
    return x == 1

def has_three_consecutive_presses(samples):
    for i in range(len(samples) - 2):
        if all(is_pressed(x) for x in samples[i:i+3]):
            return True
    return False

def has_zero_after_press(samples, presses):
    for i in range(presses + 1, len(samples)):
        if is_pressed(samples[i-presses]) and not is_pressed(samples[i]):
            return True
    return False
